package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ObjectBuffer;
import com.fasterxml.jackson.databind.deser.std.StringArrayDeserializer;
import com.fasterxml.jackson.databind.deser.std.StringDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer__deserializeCustom_TriageGen2Test {

    private StringArrayDeserializer deserializer;
    private JsonParser jp;
    private DeserializationContext ctxt;
    private ObjectBuffer buffer;
    private StringDeserializer elementDeserializer;

    // Subclass to access the protected method
    private static class TestableStringArrayDeserializer extends StringArrayDeserializer {
        public TestableStringArrayDeserializer(StringDeserializer elementDeserializer) {
            super();
            // Using reflection to set the private field _elementDeserializer if necessary, 
            // but in Jackson's StringArrayDeserializer, it is usually initialized.
            // Since we cannot easily set the private field via constructor, we use reflection.
            try {
                java.lang.reflect.Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
                field.setAccessible(true);
                field.set(this, elementDeserializer);
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        }

        @Override
        public String[] deserialize(JsonParser jp, DeserializationContext ctxt) throws IOException {
            return _deserializeCustom(jp, ctxt);
        }
    }

    @Before
    public void setUp() throws Exception {
        jp = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(ObjectBuffer.class);
        elementDeserializer = mock(StringDeserializer.class);

        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);

        // Mock buffer behavior
        // We simulate a small buffer of size 2 to trigger the 'appendCompletedChunk' logic
        Object[] initialChunk = new Object[2];
        when(buffer.resetAndStart()).thenReturn(initialChunk);

        // Mock completeAndClearBuffer to return the actual array based on the provided ix
        when(buffer.completeAndClearBuffer(any(Object[].class), anyInt(), eq(String.class)))
            .thenAnswer(invocation -> {
                Object[] chunk = invocation.getArgument(0);
                int ix = invocation.getArgument(1);
                String[] result = new String[ix];
                for (int i = 0; i < ix; i++) {
                    result[i] = (String) chunk[i];
                }
                return result;
            });

        deserializer = new TestableStringArrayDeserializer(elementDeserializer);
    }

    @Test
    public void testDeserializeEmptyArray() throws IOException {
        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);

        String[] result = deserializer.deserialize(jp, ctxt);

        assertEquals(0, result.length);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeWithValuesAndNulls() throws IOException {
        // Sequence: START_ARRAY (not explicitly handled by loop, loop starts with nextToken)
        // Actually, the loop calls nextToken() immediately. 
        // Expected sequence for ["a", null, "b"]: VALUE_STRING, VALUE_NULL, VALUE_STRING, END_ARRAY
        when(jp.nextToken())
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.VALUE_NULL)
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt))).thenReturn("a", "b");

        String[] result = deserializer.deserialize(jp, ctxt);

        assertEquals(3, result.length);
        assertArrayEquals(new String[]{"a", null, "b"}, result);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeTriggersBufferExpansion() throws IOException {
        // Initial chunk size is 2. To trigger expansion, we need 3 elements.
        // Sequence: VALUE_STRING, VALUE_STRING, VALUE_STRING, END_ARRAY
        when(jp.nextToken())
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.VALUE_STRING)
            .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt))).thenReturn("1", "2", "3");

        // Mock the appendCompletedChunk to return a larger array
        Object[] secondChunk = new Object[2];
        when(buffer.appendCompletedChunk(any(Object[].class))).thenReturn(secondChunk);

        String[] result = deserializer.deserialize(jp, ctxt);

        assertEquals(3, result.length);
        assertArrayEquals(new String[]{"1", "2", "3"}, result);
        verify(buffer, times(1)).appendCompletedChunk(any(Object[].class));
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test(expected = IOException.class)
    public void testDeserializeThrowsIOException() throws IOException {
        when(jp.nextToken()).thenThrow(new IOException("Mock error"));

        deserializer.deserialize(jp, ctxt);
    }
}
